photos = get_photos()
return { 'game_id': game_id, 'status': game.status, 'players': [{'id': p.id, 'name': p.name, 'color': p.color} for p in game.players], 'photos': photos, 'rounds': [r.to_dict() for r in sorted(game.rounds, key=lambda r: r.round_number)] }
